import ezdxf, math, csv
# independent: read routes and rises straight from the DXFs
routes={}
for f in ['E-611_level_1_power_plan','E-612_level_2_power_plan','E-613_roof_power_plan',
          'E-615_site_electrical_plan','E-616_building_4212_power_plan']:
    doc=ezdxf.readfile(f'project/drawings/{f}.dxf')
    for e in doc.modelspace():
        if e.dxftype()=='LWPOLYLINE' and e.dxf.layer.startswith('E-RTE-'):
            pts=[(p[0],p[1]) for p in e.get_points()]
            routes[e.dxf.layer[6:]]=sum(math.dist(pts[i],pts[i+1]) for i in range(len(pts)-1))
doc=ezdxf.readfile('project/drawings/E-618_riser_diagram.dxf')
rises={}
for e in doc.modelspace():
    if e.dxftype()=='TEXT' and ' RISE ' in e.dxf.text:
        head,tail=e.dxf.text.split(' RISE ')
        try: rises[head.strip()]=float(tail.replace("'",'').strip())
        except: pass
rows={r['circuit']:r for r in csv.DictReader(open('output/pkg/wire_schedule.csv'))}
bad=0
for cid,r in rows.items():
    exp=math.ceil(routes[cid]+rises[cid]+16)
    if abs(float(r['length_ft'])-exp)>1e-9:
        print('LEN MISMATCH',cid,r['length_ft'],exp); bad+=1
print('circuits',len(rows),'routes',len(routes),'rises',len(rises),'len mismatches',bad)
# also check every route/rise is used
print('unused routes',set(routes)-set(rows),'unused rises',set(rises)-set(rows))
EOF

