from core import *

def egc_for(c, mat, size, sets, base_size):
    """EGC size: table on OCPD, upsized by circular-mil ratio if phase increased above ampacity min."""
    t=egc_table(c['ocpd'])
    cm=DATA['CU'][t][0]
    if base_size is not None:
        ratio=DATA[mat][size][0]/DATA[mat][base_size][0]
        if ratio>1.0001:
            cm=cm*ratio
    return next_size_at_least(cm)

def amp_option(c,mat,size,sets,ctx=None):
    """returns (amp_per_set, detail dict) or None if infeasible"""
    if c['install'].startswith('Raceway'):
        a,ka,kg=raceway_amp(mat,size,c['amb'],c['ph'])
        cap=table(mat,size,'race',c['term'])
        return min(a,cap),dict(raw=a,ka=ka,kg=kg,cap=cap,kind='race')
    if c['install'].startswith('Cable tray'):
        N=ctx['trayN']
        a,kt,dts=tray_amp(mat,size,N)
        cap=table(mat,size,'free',c['term'])
        return min(a,cap),dict(raw=a,kt=kt,dts=dts,cap=cap,kind='tray')
    # duct
    bname='DB-1' if 'DB-1' in c['install'] else 'DB-2'
    return None,None

def base_size(c,mat,sets,ampfn):
    for i in range(0,c['maxidx']+1):
        s=SIZES[i]
        a=ampfn(s)
        if isinstance(a,tuple): a=a[0]
        if a is not None and a*sets>=c['design']-1e-9:
            return s
    return None

def cost_of(c,mat,size,sets,base_size_):
    nph=3 if c['ph']==3 else 2
    cft=c['length']*sets*nph
    e=egc_for(c,mat,size,sets,base_size_)
    eft=c['length']*sets
    p=PRICE[size]; pe=PRICE[e]
    cm,cl=(p[0],p[1]) if mat=='CU' else (p[3],p[4])
    em,el=pe[0],pe[1]
    termq=sets*2
    tm,tl=(p[6],p[7])
    cond_mat=cft*cm; cond_lab=cft*cl
    egc_mat=eft*em; egc_lab=eft*el
    term_mat=termq*tm; term_lab=termq*tl
    cond_ft=cft+eft
    cond_mat+=egc_mat; cond_lab+=egc_lab
    cond_usd=cond_mat+cond_lab
    race_mat=race_lab=0.0
    if c['install'].startswith('Raceway'):
        q=c['length']*sets
        pr=CONDUIT_PRICE[DATA[mat][size][11]]
        race_mat=q*pr*0.45; race_lab=q*pr*0.55
    return dict(cond_ft=cond_ft,cond_mat=cond_mat,cond_lab=cond_lab,cond_usd=cond_mat+cond_lab,
