import sys, csv, math
sys.path.insert(0,'work')
from core import *
rows=list(csv.DictReader(open('output/pkg/wire_schedule.csv')))
best=(0,None); jam=(99,None)
for r in rows:
    c=CIRC[r['circuit']]; s=r['size']; mat=r['material']; sets=int(r['sets'])
    n=3 if c['ph']==3 else 2
    od=DATA[mat][s][1]
    if c['install'].startswith('Raceway'):
        tr=DATA[mat][s][11]; ID=CONDUIT_ID[tr]; area=math.pi/4*ID*ID
        fill=n*math.pi/4*od*od/area
        if fill>best[0]: best=(fill,(r['circuit'],s,mat,tr,n))
        if n==3:
            jr=ID/od
            if jr<jam[0]: jam=(jr,(r['circuit'],s,tr))
    elif c['install'].startswith('Duct'):
        b=BANKS['DB-1' if 'DB-1' in c['install'] else 'DB-2']; area=math.pi/4*b['Did']**2
        fill=n*math.pi/4*od*od/area
        if fill>best[0]: best=(fill,(r['circuit'],s,mat,b['Did'],n))
        if n==3:
            jr=b['Did']/od
            if jr<jam[0]: jam=(jr,(r['circuit'],s,b['Did']))
print('worst fill',best)
print('min jam',jam)
# duct cover
for bank in ['DB-1','DB-2']:
    b=BANKS[bank]
    for d,(x,dep) in b['ducts'].items():
        od=b['Dod']; cover=dep-od/2-30
        print(bank,d,'cover over duct',round(cover,3))
